insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 5, 1, '{"place":"Reedham, and the waystone","narrated":false,"tone":"wry","cupNight":false,"opener":"North, then. That''s a long road for tired boots.","forkA":"The fifth is a Stone like the others.","forkB":"The fifth is something different.","callback":"Meira looked for a fifth and never found one. Today, on the road north, somebody had cut a line out of a stone.","nudge":"{friend:Intellect}, what would a dead city hide?","riddle":{"q":"What goes on for miles but never moves?","a":"a road","quip":"North, and mind your boots.","accept":["a road","road"],"maxTries":3},"leads":[{"id":"5-1-1","place":"the worn face of the waystone","actions":[{"attr":"Craft","verb":"run a thumb along the cut-away line"},{"attr":"Intellect","verb":"hold the light low and look at its edges"}],"clueTitle":"The crisp edge","clueText":"Frost has eaten the old carving, but the edges of the cut-out line are crisp. Not one letter of it is left.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-1-2","place":"the crack at the waystone''s foot","actions":[{"attr":"Craft","verb":"scrape back the rime with a knife"},{"attr":"Aim","verb":"watch the crack while the beat comes"}],"clueTitle":"The rime stays","clueText":"Long after the fragment is out, the rime stays in the crack, in a mild wind. It is the same cold you have felt at every hiding place since the forest road.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-1-3","place":"the lane up from the shingle","actions":[{"attr":"Charm","verb":"walk up the lane and stop at a door"},{"attr":"Aim","verb":"look up the lane from the boat"}],"clueTitle":"Every window lit","clueText":"Every window up the lane has a lamp burning at midday, as Reedham does only on a dark-moon night.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Then it began to take.\"* Take what, and from whom?","weekQuestion":"What will it take for the fifth to end this?","pull":"At dusk the heartbeat comes again. It is louder than it was at dawn.\n\n**What is left in a city where nothing grows and nobody goes? The old kingdom''s road: two days north.**"}'::jsonb),
('dark-moon', 1, 5, 2, '{"place":"The old kingdom''s road","narrated":false,"tone":"wry","cupNight":false,"opener":"The grass on a war grave shouldn''t shiver. I''d say that''s the heartbeat.","forkA":"The beat calls them north.","forkB":"The beat only maddens them.","callback":"On the Stillwater the birds went quiet at the first beat. Tonight the dogs came with it.","nudge":"{friend:Might}, you stood over the cart. Did the beat call those dogs, or only madden them?","riddle":{"q":"What bends in the wind but never breaks?","a":"grass","quip":"Not this lot.","accept":["grass"],"maxTries":3},"leads":[{"id":"5-2-1","place":"the edge of the dark, past the cart","actions":[{"attr":"Aim","verb":"watch them at the edge of the dark"},{"attr":"Might","verb":"stand over the cart and hold your ground"}],"clueTitle":"Heads down","clueText":"When the beat stops, every dog stops with it, heads down, mid-stride. Not one runs away, and not one comes on.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-2-2","place":"the bandage on the man''s forearm","actions":[{"attr":"Charm","verb":"ask to see the arm"},{"attr":"Craft","verb":"tie the bandage again, properly"}],"clueTitle":"One bite","clueText":"Under the bandage is a single bite, deep and clean. The teeth went in once and held, and nothing tore.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-2-3","place":"where the dogs came out of the dusk","actions":[{"attr":"Aim","verb":"read the ground at first light"},{"attr":"Intellect","verb":"walk their tracks back the way they came"}],"clueTitle":"Scattered","clueText":"At first light their tracks come in together, in a straight line from the north. They go out scattered every way, the prints far apart.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"That is why it had to be us.\"* Had to be them, for what?","weekQuestion":"What will it take for the fifth to end this?","pull":"**It is nearer every dusk, and it is coming from inside the city. Highwall, by noon.**"}'::jsonb),
('dark-moon', 1, 5, 3, '{"place":"The herald''s gate","narrated":false,"tone":"wry","cupNight":false,"opener":"A bar of new timber in brackets worn bright. Somebody''s been barring this gate for centuries, and the wood''s new.","forkA":"The bar keeps the world out.","forkB":"The bar keeps something in.","callback":"Upriver, somebody kept a hidden path clear and a dog on new iron. Here somebody keeps a new bar on an old gate.","nudge":"{friend:Craft}, new wood in brackets worn bright. Who keeps barring this gate?","riddle":{"q":"The more of me there is, the less you see. What am I?","a":"darkness","quip":"The city has plenty.","accept":["darkness"],"maxTries":3},"leads":[{"id":"5-3-1","place":"the street behind the gate","actions":[{"attr":"Aim","verb":"look down into the street from the walkway"},{"attr":"Agility","verb":"lean out over the inner parapet"}],"clueTitle":"One trodden path","clueText":"In the dust of the street behind the gate, one narrow path is trodden from the bar up the hill, toward the smoke.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"5-3-2","place":"the near end of the new bar","actions":[{"attr":"Aim","verb":"pick out the bar''s end from above"},{"attr":"Craft","verb":"judge the timber by its colour"}],"clueTitle":"Still white","clueText":"The bar''s cut end is still white, and the axe-marks are sharp. It was put up within the last few days.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"5-3-3","place":"the broken stair","actions":[{"attr":"Agility","verb":"climb down to the gap in the stair"},{"attr":"Craft","verb":"look at the broken edges"}],"clueTitle":"Knocked out","clueText":"The missing steps lie at the stair''s foot in big, square pieces. Every break shows the bite of a hammer, weathered smooth.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"None of us gave to the fifth.\"* Why give to four and not to the fifth?","weekQuestion":"What will it take for the fifth to end this?","pull":"**Who bars a dead city from the inside, year after year? Down into the streets, following the wall.**"}'::jsonb),
('dark-moon', 1, 5, 4, '{"place":"The dead streets","narrated":false,"tone":"quiet","cupNight":true,"opener":"Nobody''s kept a fire here for us. Keep this one small.","forkA":"The soldiers are only standing.","forkB":"One helm has turned.","callback":"On the road, when the beat stopped, the dogs stopped where they stood. These soldiers stopped mid-stride, and never started again.","nudge":"{friend:Aim}, did one of those helms turn, or did the dusk play tricks?","riddle":{"q":"What turns but never leaves its post?","a":"a weathervane","quip":"The wind decides. Mostly.","accept":["a weathervane","weathervane"],"maxTries":3},"leads":[{"id":"5-4-1","place":"the ground round the soldiers","actions":[{"attr":"Aim","verb":"look at the street round them"},{"attr":"Craft","verb":"crouch and look at the dust"}],"clueTitle":"Unbroken dust","clueText":"Round every boot the dust lies in one even skin. The only prints in it are yours.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"5-4-2","place":"the barred door of the empty house","actions":[{"attr":"Aim","verb":"keep an eye to the crack in the door"},{"attr":"Agility","verb":"sit by the door, ready, and listen"}],"clueTitle":"Metal on stone","clueText":"As the light goes, one sound comes from the direction of the street of soldiers: metal on stone, once. Then nothing.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"5-4-3","place":"the helms down the street","actions":[{"attr":"Aim","verb":"look along the line of helms"},{"attr":"Intellect","verb":"set each helm against the next"}],"clueTitle":"No two alike","clueText":"Every helm sits a little crooked on its neck, this way or that, no two the same. From the end of the street, any one of them could look turned.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We could not bring ourselves to break them.\"* Why not?","weekQuestion":"What will it take for the fifth to end this?","pull":"**Was that helm turned before? Nobody is sure. And the smoke is higher up the hill. The square below the hall.**"}'::jsonb),
('dark-moon', 1, 5, 5, '{"place":"Below the hall","narrated":false,"tone":"wry","cupNight":false,"opener":"One chalk stroke each dusk. Somebody''s counting.","forkA":"Their count began when the Stones drank.","forkB":"Their count was set long ago.","callback":"At Reedham they kept Joss eight nights, waiting for something. Here they strike off one night every dusk.","nudge":"{friend:Intellect}, what ends when the count ends?","riddle":{"q":"What burns shorter every night but is never cut?","a":"a candle","quip":"Fires and candles, same trade.","accept":["a candle","candle"],"maxTries":3},"leads":[{"id":"5-5-1","place":"the board propped by the wall","actions":[{"attr":"Aim","verb":"read the board from the rubble"},{"attr":"Agility","verb":"creep close enough to see the chalk"}],"clueTitle":"One hand","clueText":"Every stroke on the board is in the same thick, square hand, the crossed ones and the ones still to cross. The chalk has been gone over many times, never redrawn.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-5-2","place":"the hooded figures at the fire","actions":[{"attr":"Aim","verb":"watch their faces from the rubble"},{"attr":"Agility","verb":"crawl close enough to see them"}],"clueTitle":"Every head lifts","clueText":"Every one of them sits facing the doors. When the beat comes, every head lifts at once, and stays lifted until it has passed.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-5-3","place":"the shell of the house across the square","actions":[{"attr":"Agility","verb":"slip round to its back wall"},{"attr":"Aim","verb":"look in through the broken window"}],"clueTitle":"More bedrolls","clueText":"Round the fire lie more bedrolls than there are people at it, each one rolled tight and tied.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Where we could watch it, and watch him.\"* Why keep the two so close?","weekQuestion":"What will it take for the fifth to end this?","pull":"**Counting down to what? You hold five pieces, and the trail began on the wall. The wall again.**"}'::jsonb),
('dark-moon', 1, 5, 6, '{"place":"The wall again","narrated":false,"tone":"wry","cupNight":false,"opener":"A slit window, a hidden room, a night nobody heard you.","forkA":"The room was built to hide the fifth.","forkB":"The room was built to watch the hall.","callback":"Every map before tonight was read out loud. Tonight it went hand to hand, and nobody heard.","nudge":"{friend:Aim}, what can you see through one slit?","riddle":{"q":"What gets bigger the more you take away?","a":"a hole","quip":"A room hollowed out of a wall is one.","accept":["a hole","hole"],"maxTries":3},"leads":[{"id":"5-6-1","place":"the city side of the wall, below the walk","actions":[{"attr":"Aim","verb":"lean out over the parapet"},{"attr":"Might","verb":"brace on the parapet and lean far out"}],"clueTitle":"The narrow slit","clueText":"The slit is no wider than a hand, low in the wall''s face. Unless you lean out over the parapet and look straight down the stone, you cannot see it at all.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-6-2","place":"the parapet on the city side","actions":[{"attr":"Craft","verb":"run a hand along the parapet''s top"},{"attr":"Might","verb":"lean your weight where others leaned"}],"clueTitle":"Two shallow dips","clueText":"Above where the map points, the parapet''s top is worn into two shallow dips, the width of a pair of elbows. They face the hall.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-6-3","place":"the forty paces of open stone","actions":[{"attr":"Agility","verb":"pace the walk while their heads are turned"},{"attr":"Intellect","verb":"measure the walk against the gate-tower"}],"clueTitle":"A stride wider","clueText":"Here the walk is wider than at the gate, by a good stride. All of the extra width is on the city side.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Where he fell, under the dark moon, the five were joined.\"* Why there, and why that night?","weekQuestion":"What will it take for the fifth to end this?","pull":"**The watch has changed. It is dark enough. Into the wall, tonight.**"}'::jsonb)
